function renderAIText(text){
 const lines=String(text||'').split('\n'),box=h('div',{class:'ai-result'});let i=0;
 const plain=s=>s.replace(/^#+\s*/u,'').replace(/\*\*/gu,'').replace(/`/gu,'').trim();
 const cells=s=>s.trim().replace(/^\|/u,'').replace(/\|$/u,'').split('|').map(x=>plain(x));
 while(i<lines.length){const line=lines[i].trim();if(!line){i++;continue;}
  if(line.startsWith('|')&&lines[i+1]?.trim().startsWith('|')){const heads=cells(line);i++;if(cells(lines[i]).every(v=>/^:?-+:?$/.test(v)))i++;const body=h('tbody');while(i<lines.length&&lines[i].trim().startsWith('|'))body.append(h('tr',{},cells(lines[i++]).map(c=>h('td',{},c))));box.append(h('div',{class:'tablewrap'},h('table',{},h('thead',{},h('tr',{},heads.map(c=>h('th',{scope:'col'},c)))),body)));continue;}
  if(/^[-*]\s/u.test(line)){const ul=h('ul');while(i<lines.length&&/^\s*[-*]\s/u.test(lines[i]))ul.append(h('li',{},plain(lines[i++].replace(/^\s*[-*]\s/u,''))));box.append(ul);continue;}
  if(/^#{1,6}\s|^PHẦN\s|^BẢN\s|^KẾ HOẠCH|^E[12]\./u.test(line)||/^\*\*.+\*\*$/u.test(line))box.append(h('h3',{},plain(line)));else if(!/^[-_]{3,}$/u.test(line))box.append(h('p',{},plain(line)));i++;
 }
 box.append(h('details',{},h('summary',{},'Xem nguyên văn kết quả Gemini'),h('pre',{},text)));return box;
}
